# o6_10 – Zugangsvoraussetzungen, Vertragszustandekommen und Vertragsgültigkeit
package oepul.o6_10

applicant := object.get(input, ["farm", "applicant"], {})

# --- Beantragung (O610-APP-DEADLINE, O610-APP-LAST-ENTRY) --------------------------

application_date := d if {
	d := object.get(o610, "measure_application_date", null)
	d != null
}

# Vertragsbeginn = 1.1. des Folgejahres der fristgerechten Beantragung (bis 31.12.)
contract_start_year := year_of(application_date) + 1

applied_via_measure_application if {
	contract_start_year <= params.last_entry_funding_year
	contract_start_year <= year
}

# --- Maßnahmenübernahme (O610-GEN-TAKEOVER) ----------------------------------------

takeover := object.get(o610, "takeover", {})

takeover_deadline_md := params.takeover_deadline_month_day_2023_2028 if {
	year in {2023, 2028}
}

else := params.takeover_deadline_month_day

takeover_valid if {
	object.get(takeover, "is_takeover", false) == true
	date_ns(takeover.request_date) <= md_ns(year, takeover_deadline_md)
	year_of(takeover.request_date) == year
	object.get(takeover, "farm_already_participating", false) == false
	object.get(takeover, "additional_area_ha", 0) <= (object.get(takeover, "taken_over_area_ha", 0) * params.takeover_max_extension_percent) / 100
}

takeover_rejections contains {"rule_id": "O610-GEN-TAKEOVER", "reason": msg} if {
	object.get(takeover, "is_takeover", false) == true
	not takeover_valid
	msg := "Maßnahmenübernahme unzulässig (Frist 15.04./17.04., bisher nicht teilnehmender Betrieb, Ausweitung höchstens 50 %)"
}

has_commitment_basis if applied_via_measure_application

has_commitment_basis if takeover_valid

# --- Abmeldung / Ausstieg (O610-EXIT-TIMING, O610-GEN-EXIT-CONTROL-LIMIT, O610-GEN-REENTRY) ---

deregistration_date := d if {
	d := object.get(o610, "deregistration_date", null)
	d != null
}

control_announced_date := d if {
	d := object.get(o610, "on_site_control_announced_date", null)
	d != null
}

# Ausstieg nach Ankündigung/Durchführung einer Vor-Ort-Kontrolle desselben Jahres ist nicht mehr möglich
deregistration_blocked if {
	year_of(control_announced_date) == year_of(deregistration_date)
	date_ns(deregistration_date) >= date_ns(control_announced_date)
}

# Neuerliche Beantragung nach der Abmeldung (Wiedereinstieg) hebt die Abmeldung für Folgejahre auf
reentered_after_deregistration if {
	date_ns(application_date) > date_ns(deregistration_date)
}

deregistered_for_year if {
	not deregistration_blocked
	not reentered_after_deregistration
	year_of(deregistration_date) <= year
}

# --- Förderwerbende Person (O610-GEN-APPLICANT-TYPES, O610-GEN-PUBLIC-AUTHORITY-10) ----

eligible_person_types := {t.person_type | some t in defs.eligible_applicant_types}

public_body if applicant.person_type == "territorial_authority"

public_body if object.get(applicant, "public_authority_share_percent", 0) > params.public_authority_max_share_percent

public_body_allowed_for_measure_10 if {
	some e in defs.public_authority_exception_measures
	e.measure == params.measure_code
	e.from_year <= year
	year <= e.to_year
}

access_violations contains {
	"rule_id": "O610-GEN-PUBLIC-AUTHORITY-10",
	"reason": "Gebietskörperschaften bzw. Einrichtungen mit mehr als 25 % Beteiligung von Gebietskörperschaften sind ab dem Antragsjahr 2025 nicht förderwerbend",
} if {
	public_body
	not public_body_allowed_for_measure_10
}

access_violations contains {
	"rule_id": "O610-GEN-APPLICANT-TYPES",
	"reason": sprintf("Personentyp '%s' ist keine zulässige förderwerbende Person", [object.get(applicant, "person_type", "unbekannt")]),
} if {
	not public_body
	not object.get(applicant, "person_type", "natural_person") in eligible_person_types
}

access_violations contains {
	"rule_id": "O610-GEN-APPLICANT-OWN-ACCOUNT",
	"reason": sprintf("Voraussetzung '%s' der förderwerbenden Person nicht erfüllt", [field]),
} if {
	some field in ["is_active_farmer", "farms_in_own_name_and_account"]
	object.get(applicant, field, true) == false
}

# --- Mindestteilnahmefläche (O610-MIN-AREA, O610-CONTRACT-LAPSE-MIN-AREA) -----------

access_violations contains {
	"rule_id": "O610-MIN-AREA",
	"reason": sprintf("Nur %.2f ha Wein-, Obst- oder Hopfenflächen; Mindestteilnahmefläche 0,50 ha", [vfh_area_ha]),
} if {
	vfh_area_ha < params.min_participation_area_ha
}

# --- Betriebsmindestgröße im ersten ÖPUL-Jahr (O610-GEN-FARM-MIN-SIZE) --------------

first_oepul_year if object.get(input, ["farm", "oepul", "first_oepul_participation_year"], null) == year

access_violations contains {
	"rule_id": "O610-GEN-FARM-MIN-SIZE",
	"reason": "Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr (1,50 ha bzw. 0,50 ha geschützter Anbau) nicht erreicht",
} if {
	first_oepul_year
	object.get(input, ["land", "total_area_ha"], 0) < params.farm_min_size_first_year_ha
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) < params.farm_min_size_first_year_protected_cultivation_ha
}

# --- Programmende ------------------------------------------------------------------

access_violations contains {
	"rule_id": "O610-CONTRACT-PERIOD",
	"reason": "Antragsjahr außerhalb der Programmlaufzeit 2023 bis 2028",
} if {
	not year in numbers.range(2023, 2028)
}

# --- Mehrfachantrag als Zahlungsantrag (O610-GEN-PREAPPLICATION) --------------------

payment_application_missing if object.get(o610, "multiple_application_submitted", true) == false

# --- Ergebnis: Vertrag/Teilnahme im Antragsjahr -------------------------------------

default contract_valid := false

contract_valid if {
	has_commitment_basis
	not deregistered_for_year
	count(access_violations) == 0
}

contract_status := "no_application" if {
	not has_commitment_basis
	count(takeover_rejections) == 0
}

else := "takeover_rejected" if {
	not has_commitment_basis
}

else := "deregistered" if {
	deregistered_for_year
}

else := "lapsed_access_conditions_not_met" if {
	count(access_violations) > 0
}

else := "valid"

# O610-EXIT-AFTER-1Y: Ausstieg frühestens nach Erfüllung des einjährigen Vertragszeitraums
default exit_possible_from_year := null

exit_possible_from_year := contract_start_year + 1 if applied_via_measure_application

# o6_10 – Maßnahmenkombination (Anhang L), Einstufung als einjährige Maßnahme, Hinweise
package oepul.o6_10

annex_l := data.o6_10.annex_l_combination_table

annex_l_cell(row, col) := c if {
	some c in annex_l.cells
	c.row_measure == row
	c.column_measure == col
}

# O610-COMB-ANNEX-L: auf der Einzelfläche mit Maßnahme 10 kombinierbare Maßnahmen
combinable_with_10 := {c.column_measure | some c in annex_l.cells; c.row_measure == params.measure_code}

combination_conflicts contains {
	"parcel_id": p.parcel_id,
	"measure": m,
	"rule_id": "O610-COMB-ANNEX-L",
	"reason": sprintf("Maßnahme %s ist gemäß Anhang L auf der Einzelfläche nicht mit Maßnahme 10 kombinierbar", [m]),
} if {
	some p in vfh_parcels
	some m in parcel_measures(p)
	m != params.measure_code
	not m in combinable_with_10
}

combination_notes contains {
	"parcel_id": p.parcel_id,
	"measure": m,
	"rule_id": "O610-COMB-ANNEX-L",
	"footnotes": [annex_l.footnotes[f] | some f in annex_l_cell(params.measure_code, m).footnotes],
} if {
	some p in vfh_parcels
	some m in parcel_measures(p)
	m in combinable_with_10
	count(annex_l_cell(params.measure_code, m).footnotes) > 0
}

# O610-GEN-ONE-YEAR-CLASS: Maßnahme 10 ist einjährig
measure_is_one_year if {
	some m in data.o6_10.measure_catalog.one_year_measures
	m.code == params.measure_code
}

area_access_restricted if params.measure_code in data.o6_10.measure_catalog.area_access_restricted_measures

# O610-GEN-ONE-YEAR-OPTIONS-2028: Zuschläge bei einjährigen Maßnahmen bis inkl. Förderjahr 2028
supplement_application_possible if {
	measure_is_one_year
	year <= params.supplement_last_funding_year
}

# O610-GEN-CONDITIONALITY: Hinweis auf Kürzung nach Art. 83–89 VO (EU) 2021/2116
notices contains {
	"rule_id": "O610-GEN-CONDITIONALITY",
	"notice": "Konditionalitätsverstoß gemeldet: Kürzung gemäß Art. 83 bis 86 bzw. 87 bis 89 VO (EU) 2021/2116 zusätzlich zur Maßnahmenprämie",
} if {
	object.get(input, ["farm", "oepul", "conditionality_breach"], false) == true
}

notices contains {
	"rule_id": "O610-GEN-COMBINATION-CORRECTION",
	"notice": "Unmögliche Maßnahmenkombination: Korrektur bis zum Erhalt der Auszahlungsmitteilung zulässig, sofern keine Beanstandung bei einer Vor-Ort-Kontrolle vorliegt",
} if {
	count(combination_conflicts) > 0
}

notices contains {
	"rule_id": "O610-2026-DROUGHT-GREENING",
	"notice": "Dürre 2026: fehlende Flächendeckung bzw. Ausfallgetreide über 50 % trotz ordnungsgemäßer Anlage wird automatisch als höhere Gewalt anerkannt (keine Meldung erforderlich)",
} if {
	count(drought_2026_relief_parcels) > 0
}

notices contains {
	"rule_id": "O610-2026-EXIT12-EOP",
	"notice": "Rückzahlungsfreier Ausstieg aus Maßnahme 12 im Jahr 2026: Maßnahme 12 nicht mehr in participating_measures führen, sofern Ausstieg genehmigt (Annahme A-12)",
} if {
	year == 2026
	object.get(input, ["farm", "oepul", "exited_measure_12_rebzikade_2026"], false) == true
	"12" in participating_measures
}

notices contains {
	"rule_id": "O610-GEN-MIN-PAYOUT",
	"notice": "Auszahlungsbetrag übersteigt 50 Euro nicht: von der Gewährung kann abgesehen werden",
} if {
	below_minimum_payout
}

notices contains {
	"rule_id": "O610-GEN-CONTROL-REFUSAL",
	"notice": "Kontrolle verweigert bzw. verhindert: Antrag abzulehnen, keine Prämie für das laufende Jahr",
} if {
	control_refused
}

notices contains {
	"rule_id": "O610-GEN-PREAPPLICATION",
	"notice": "Kein Mehrfachantrag mit förderrelevanten Flächen abgegeben: keine Zahlung im Antragsjahr",
} if {
	payment_application_missing
}

# o6_10 – Teilnahmefähige Flächen und Prämienausschlüsse je Schlag
package oepul.o6_10

# O610-GEN-DEF-FRUIT: Obstkulturen gemäß Definition (inkl. Erweiterung ab 2025)
valid_fruit_name(name) if {
	some f in defs.fruit_crops
	f.name == name
	f.from_year <= year
}

valid_fruit_name(name) if {
	target := defs.fruit_crop_aliases[name]
	some f in defs.fruit_crops
	f.name == target
	f.from_year <= year
}

fruit_species_ok(p) if effective_crop_type(p) != "fruit"

fruit_species_ok(p) if {
	effective_crop_type(p) == "fruit"
	object.get(p, ["crop", "crop_name"], null) == null
}

fruit_species_ok(p) if {
	effective_crop_type(p) == "fruit"
	valid_fruit_name(p.crop.crop_name)
}

# O610-GEN-LOCATION-AT
located_in_austria(p) if object.get(p, ["location", "is_in_austria"], true) == true

# O610-ELIG-ONLY-VFH / O610-ELIG-ALL-AREAS: Wein-, Obst-, Hopfen- und Weinterrassenflächen des Betriebes
vfh_parcel(p) if {
	effective_crop_type(p) in eligible_crop_types
	fruit_species_ok(p)
	located_in_austria(p)
	object.get(p, "is_gloez_landscape_element", false) != true
}

vfh_parcels := [p | some p in parcels; vfh_parcel(p)]

vfh_area_ha := sum([parcel_area(p) | some p in vfh_parcels])

# Gründe, warum ein Schlag nicht teilnahmefähig ist (O610-ELIG-ONLY-VFH, O610-GEN-NONELIG-AREAS)
ineligible_parcels contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-ELIG-ONLY-VFH",
	"reason": sprintf("Kulturart '%s' ist keine teilnahmefähige Wein-, Obst- oder Hopfenfläche", [effective_crop_type(p)]),
} if {
	some p in parcels
	declared_crop_type(p) != "none"
	not effective_crop_type(p) in eligible_crop_types
}

ineligible_parcels contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GEN-DEF-FRUIT",
	"reason": sprintf("'%s' ist im Antragsjahr %d keine Obstkultur im Sinne des ÖPUL 2023", [p.crop.crop_name, year]),
} if {
	some p in parcels
	effective_crop_type(p) == "fruit"
	not fruit_species_ok(p)
}

ineligible_parcels contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GEN-LOCATION-AT",
	"reason": "Fläche liegt nicht in Österreich",
} if {
	some p in parcels
	effective_crop_type(p) in eligible_crop_types
	not located_in_austria(p)
}

ineligible_parcels contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GEN-NONELIG-AREAS",
	"reason": "GLÖZ-Landschaftselement ist nicht förderfähig",
} if {
	some p in parcels
	object.get(p, "is_gloez_landscape_element", false) == true
}

# Prämienausschlüsse auf teilnahmefähigen Schlägen
premium_exclusions contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GEN-OP-CODE",
	"reason": "Schlag mit ÖPUL-Code OP: keine ÖPUL-Prämie im Förderjahr",
} if {
	some p in vfh_parcels
	params.op_code in parcel_codes(p)
}

premium_exclusions contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GEN-OP-MEASURE-SPECIFIC",
	"reason": "Maßnahmenbezogener OP-Code für Maßnahme 10: keine Prämie in dieser Maßnahme",
} if {
	some p in vfh_parcels
	params.measure_code in {m | some m in object.get(p, "op_excluded_measures", [])}
}

premium_exclusions contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GEN-TRIAL-AREAS",
	"reason": "Versuchsfläche (Code VF): keine Prämie im laufenden Antragsjahr",
} if {
	some p in vfh_parcels
	params.trial_area_code in parcel_codes(p)
}

premium_exclusions contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GEN-NATIONAL-PARK",
	"reason": sprintf("Nationalpark '%s': keine Prämie für Maßnahme 10", [np.park_id]),
} if {
	some p in vfh_parcels
	some np in defs.national_parks
	np.park_id == object.get(p, ["location", "national_park"], null)
	np.o6_10_premium_possible == false
}

premium_exclusions contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-FRUIT-GRAFTED",
	"reason": "Obstanlage ohne veredeltes Pflanzgut: keine ÖPUL-Prämie",
} if {
	some p in vfh_parcels
	effective_crop_type(p) == "fruit"
	object.get(p, ["permanent_crop", "is_grafted_planting_material"], null) == false
}

premium_exclusions contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GEN-TRANSFER-MIDYEAR",
	"reason": "Unterjährig weitergegebene Fläche ohne Weiterführung bis Jahresende: keine Prämie",
} if {
	some p in vfh_parcels
	object.get(p, ["transfer", "transferred_during_year"], false) == true
	object.get(p, ["transfer", "successor_continues_until_year_end"], false) != true
}

premium_exclusions contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GEN-MIN-MGMT-PERMANENT",
	"reason": sprintf("Mindestbewirtschaftungskriterium '%s' auf Dauerkulturfläche nicht erfüllt", [criterion]),
} if {
	some p in vfh_parcels
	some criterion in ["properly_planted", "annual_care", "harvest_and_removal"]
	object.get(p, ["permanent_crop", "minimum_management", criterion], true) == false
}

premium_excluded_ids := {e.parcel_id | some e in premium_exclusions}

premium_parcels := [p | some p in vfh_parcels; not p.parcel_id in premium_excluded_ids]

# ÖPUL 2023 – Erosionsschutz Wein, Obst und Hopfen (o6_10) – Hilfsfunktionen
# Gemeinsame Konstanten, Datenzugriffe und Datums-/Flächenfunktionen.
package oepul.o6_10

# Datentabellen (data/o6_10/*.json)
params := data.o6_10.programme_parameters

defs := data.o6_10.definitions

rates := data.o6_10.premium_rates

year := input.farm.year

parcels := object.get(input, ["land", "parcels"], [])

o610 := object.get(input, ["farm", "oepul", "o6_10"], {})

participating_measures := {m | some m in object.get(input, ["farm", "oepul", "participating_measures"], [])}

nanos_per_day := ((24 * 60) * 60) * 1000000000

# Datum (YYYY-MM-DD) in Nanosekunden
date_ns(d) := time.parse_ns("2006-01-02", d)

# Datum aus Jahr und "MM-DD"
md_ns(y, md) := date_ns(sprintf("%04d-%s", [y, md]))

year_of(d) := time.date(date_ns(d))[0]

min_num(a, b) := a if a <= b

else := b

max_num(a, b) := a if a >= b

else := b

parcel_codes(p) := {c | some c in object.get(p, "oepul_codes", [])}

parcel_measures(p) := {m | some m in object.get(p, "oepul_measures", [])}

parcel_area(p) := object.get(p, "area_ha", 0)

# Neigung (fehlend/null => 0 %, siehe notes/assumptions.md)
slope_of(p) := s if {
	s := object.get(p, "slope_percent", null)
	s != null
}

else := 0

# Deklarierte Dauerkulturart; Rückfall auf crop.crop_category des Canonical Profile
declared_crop_type(p) := t if {
	t := object.get(p, ["permanent_crop", "type"], null)
	t != null
}

else := "vine" if {
	p.crop.crop_category == "vineyard"
}

else := "fruit" if {
	p.crop.crop_category == "orchard"
}

else := "hop" if {
	p.crop.crop_category == "hop"
}

else := "none"

# O610-ELIG-TERRACE-SLOPE: Terrassen nur mit mind. 25 % durchschnittlicher Hangneigung;
# darunter wird die Fläche als normale Weinfläche behandelt (Annahme A-03).
effective_crop_type(p) := "vine" if {
	declared_crop_type(p) == "vine_terrace"
	slope_of(p) < params.terrace_min_avg_slope_percent
}

else := declared_crop_type(p)

is_terrace(p) if effective_crop_type(p) == "vine_terrace"

eligible_crop_types := {t.type | some t in defs.eligible_crop_types}

premium_group(p) := t.premium_group if {
	some t in defs.eligible_crop_types
	t.type == effective_crop_type(p)
}

default premium_group_of_type(_) := "none"

premium_group_of_type(ct) := t.premium_group if {
	some t in defs.eligible_crop_types
	t.type == ct
}

# o6_10 – Förderverpflichtungen (Begrünung, Bodenbearbeitung, Nutzung, Pflanzenschutz, Aufzeichnungen)
package oepul.o6_10

greening(p) := object.get(p, ["operations", "inter_row_greening"], {})

# Begrünungspflicht auf allen Wein-, Obst- und Hopfenflächen außer Terrassen (O610-GREEN-TERRACE-EXEMPT)
greening_required(p) if {
	vfh_parcel(p)
	not is_terrace(p)
}

greening_parcels := [p | some p in parcels; greening_required(p)]

# O610-2026-DROUGHT-GREENING: 2026 keine Beanstandung bei ordnungsgemäßer Anlage
drought_2026_relief(p) if {
	year == data.o6_10.drought_2026.year
	params.measure_code in {m | some m in data.o6_10.drought_2026.greening_coverage_relief_measures}
	object.get(greening(p), "properly_established", false) == true
}

drought_2026_relief_parcels contains p.parcel_id if {
	some p in greening_parcels
	drought_2026_relief(p)
	coverage_or_volunteer_cereal_shortfall(p)
}

coverage_or_volunteer_cereal_shortfall(p) if object.get(greening(p), "full_coverage_all_inter_rows_all_year", false) != true

coverage_or_volunteer_cereal_shortfall(p) if cereal_share_exceeded(p)

cereal_share_exceeded(p) if {
	share := object.get(greening(p), "max_cereal_maize_share_percent", null)
	share != null
	share > params.max_cereal_maize_share_percent
	object.get(greening(p), "cereal_is_oat_or_spring_barley_nurse_crop", false) != true
}

# --- Ganzjährige, flächendeckende Begrünung ------------------------------------------

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GREEN-ALLYEAR-FULL",
	"reason": "Keine ganzjährige, flächendeckende Begrünung in allen Fahrgassen",
} if {
	some p in greening_parcels
	object.get(greening(p), "full_coverage_all_inter_rows_all_year", false) != true
	not drought_2026_relief(p)
}

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GREEN-ESTABLISHMENT",
	"reason": "Weder Einsaat einer Begrünungsmischung noch Belassen einer bestehenden Begrünung",
} if {
	some p in greening_parcels
	not object.get(greening(p), "establishment_method", "none") in {"sown_mixture", "existing_greening_retained"}
}

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GREEN-ESTABLISHMENT",
	"reason": sprintf("Einsaat mit nur %v winterharten Mischungspartnern (mindestens 3)", [n]),
} if {
	some p in greening_parcels
	object.get(greening(p), "establishment_method", "none") == "sown_mixture"
	n := object.get(greening(p), "winter_hardy_mixture_partners", 0)
	n < params.min_winter_hardy_mixture_partners
}

# --- Unzulässige Begrünungskulturen ---------------------------------------------------

invalid_cover_rule := {
	"organic_mulch": "O610-GREEN-INVALID-MULCH",
	"self_greening": "O610-GREEN-INVALID-SELF",
	"none": "O610-GREEN-ALLYEAR-FULL",
}

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": invalid_cover_rule[t.cover_type],
	"reason": sprintf("Unzulässige Bodenbedeckung: %s", [t.label]),
} if {
	some p in greening_parcels
	some t in defs.invalid_greening_cover_types
	object.get(greening(p), "cover_type", "living_greening") == t.cover_type
}

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GREEN-INVALID-CEREAL-MAIZE",
	"reason": "Einsaat von Getreide (ausgenommen Grünschnittroggensorten) oder Mais ist keine gültige Begrünungskultur",
} if {
	some p in greening_parcels
	object.get(greening(p), "contains_pure_cereal_or_maize", false) == true
	object.get(greening(p), "is_green_cut_rye_variety", false) != true
}

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GREEN-CEREAL-SHARE-50",
	"reason": "Anteil Getreide bzw. Mais im Bestand über 50 %",
} if {
	some p in greening_parcels
	cereal_share_exceeded(p)
	not drought_2026_relief(p)
}

# --- Offenhalten des Stammbereichs / 60 %-Regel ----------------------------------------

open_strip_max_cm(p) := defs.greening_open_strip_max_cm[effective_crop_type(p)]

open_strip_exceeded(p) if {
	w := object.get(greening(p), "open_strip_width_cm", null)
	w != null
	w > open_strip_max_cm(p)
}

single_row_system(p) if object.get(p, ["permanent_crop", "planting_system"], "single_row") == "single_row"

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GREEN-OPEN-STRIP",
	"reason": sprintf("Offengehaltener Bereich um die Stämme breiter als %v cm", [open_strip_max_cm(p)]),
} if {
	some p in greening_parcels
	single_row_system(p)
	open_strip_exceeded(p)
}

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GREEN-60PCT-ALT-SYSTEMS",
	"reason": "Abweichendes Pflanzsystem: weniger als 60 % der Gesamtfläche begrünt",
} if {
	some p in greening_parcels
	not single_row_system(p)
	open_strip_exceeded(p)
	object.get(greening(p), "greened_share_of_total_area_percent", 0) < params.alternative_planting_min_greened_share_percent
}

# --- Bodenbearbeitung, Erneuerung, Neuanlage -------------------------------------------

events(p) := object.get(greening(p), "events", [])

destructive_event(e) if e.event_type in {"break", "clearing"}

destructive_event(e) if {
	e.event_type == "other_tillage"
	object.get(e, "destroys_greening", true) == true
}

renewal_event(e) if e.event_type == "break"

renewal_event(e) if {
	e.event_type == "other_tillage"
	object.get(e, "destroys_greening", true) == true
}

# Anker des Neuanlagefensters: bei Rodung ggf. die nachfolgende Neuauspflanzung (Annahme A-06)
window_anchor(p, e) := max([date_ns(r.date) |
	some r in events(p)
	r.event_type == "replanting"
	date_ns(r.date) >= date_ns(e.date)
]) if {
	e.event_type == "clearing"
	count([1 |
		some r in events(p)
		r.event_type == "replanting"
		date_ns(r.date) >= date_ns(e.date)
	]) > 0
}

else := date_ns(e.date)

late_clearing(e) if {
	e.event_type == "clearing"
	date_ns(e.date) > md_ns(year_of(e.date), params.late_clearing_after_month_day)
}

# Rodung nach dem 15.09.: Fläche darf bis 15.05. des Folgejahres unbegrünt bleiben
late_clearing_deadline_ns(e) := md_ns(year_of(e.date) + 1, params.late_clearing_ungreened_until_month_day)

# Sonst: innerhalb von 8 Wochen, jedoch spätestens bis 01.10.
regular_deadline_ns(p, e) := min_num(
	window_anchor(p, e) + (params.reestablishment_max_days_after_break * nanos_per_day),
	md_ns(year_of(e.date), params.reestablishment_latest_month_day),
)

establishment_between(p, from_ns, to_ns) if {
	some r in events(p)
	r.event_type == "establishment"
	date_ns(r.date) >= from_ns
	date_ns(r.date) <= to_ns
}

reestablished(p, e) if {
	late_clearing(e)
	establishment_between(p, date_ns(e.date), late_clearing_deadline_ns(e))
}

reestablished(p, e) if {
	not late_clearing(e)
	establishment_between(p, date_ns(e.date), regular_deadline_ns(p, e))
}

# Neuanlage bis 15.05. des Folgejahres liegt ggf. außerhalb der Jahresaufzeichnungen:
# nur prüfen, wenn Folgejahr-Ereignisse vorliegen oder die Frist im Auswertungsjahr endet (Annahme A-07)
late_clearing_pending(p, e) if {
	late_clearing(e)
	count([r |
		some r in events(p)
		year_of(r.date) > year_of(e.date)
	]) == 0
}

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": rule_id,
	"reason": sprintf("Keine fristgerechte Neuanlage der Begrünung nach '%s' am %s", [e.event_type, e.date]),
} if {
	some p in greening_parcels
	some e in events(p)
	destructive_event(e)
	not reestablished(p, e)
	not late_clearing_pending(p, e)
	rule_id := tillage_rule_id(e)
}

# Offene Frist nach später Rodung (Neuanlage bis 15.05. des Folgejahres)
pending_reestablishments contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-TILLAGE-LATE-CLEARING",
	"deadline": sprintf("%d-%s", [year_of(e.date) + 1, params.late_clearing_ungreened_until_month_day]),
} if {
	some p in greening_parcels
	some e in events(p)
	late_clearing_pending(p, e)
	not reestablished(p, e)
}

tillage_rule_id(e) := "O610-TILLAGE-LATE-CLEARING" if late_clearing(e)

else := "O610-TILLAGE-REESTABLISH-8W"

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-TILLAGE-RENEWAL-ONCE",
	"reason": sprintf("%d Erneuerungen der Begrünung im Jahr %d (zulässig: einmal im Jahr)", [n, year]),
} if {
	some p in greening_parcels
	n := count([e |
		some e in events(p)
		renewal_event(e)
		year_of(e.date) == year
	])
	n > params.max_renewals_per_year
}

# --- Nutzungsverbot, Beweidung ---------------------------------------------------------

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-USE-BAN",
	"reason": "Nutzung des Begrünungsaufwuchses bzw. Abtransport des Mähguts",
} if {
	some p in greening_parcels
	object.get(greening(p), "growth_used_or_removed", false) == true
}

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-USE-GRAZING-EXC",
	"reason": sprintf("Unzulässige Beweidung: %s", [g.label]),
} if {
	some p in greening_parcels
	some g in defs.grazing_types
	g.grazing == object.get(greening(p), "grazing", "none")
	g.allowed == false
}

# --- Pflanzenschutz auf der Begrünung ---------------------------------------------------

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-PSM-BAN-GREENING",
	"reason": "Pflanzenschutzmitteleinsatz auf der Begrünung der Fahrgassen",
} if {
	some p in greening_parcels
	object.get(greening(p), "psm_applied_on_greening", false) == true
}

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-REMOVAL-MECHANICAL",
	"reason": sprintf("Beseitigung der Begrünung nicht mechanisch: %s", [m.label]),
} if {
	some p in greening_parcels
	some m in defs.greening_removal_methods
	m.method == object.get(greening(p), "removal_method", "none")
	m.allowed == false
}

# --- Kennzeichnungspflichten (Code OP) --------------------------------------------------

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-FRUIT-GRAFTED",
	"reason": "Unveredelte Obstbäume sind mit dem Code OP zu beantragen",
} if {
	some p in vfh_parcels
	effective_crop_type(p) == "fruit"
	object.get(p, ["permanent_crop", "is_grafted_planting_material"], null) == false
	not params.op_code in parcel_codes(p)
}

obligation_violations contains {
	"parcel_id": p.parcel_id,
	"rule_id": "O610-GEN-TRANSFER-MIDYEAR",
	"reason": "Weitergegebene Fläche ohne Weiterführung durch Übernehmer ist mit Code OP bzw. maßnahmenbezogenem OP-Code zu versehen",
} if {
	some p in vfh_parcels
	object.get(p, ["transfer", "transferred_during_year"], false) == true
	object.get(p, ["transfer", "successor_continues_until_year_end"], false) != true
	not params.op_code in parcel_codes(p)
	not params.measure_code in {m | some m in object.get(p, "op_excluded_measures", [])}
}

# --- Aufzeichnungen (O610-REC-GREENING) --------------------------------------------------

greening_record_items := {i | some i in object.get(input, ["documentation", "o6_10_greening_record_items"], [])}

missing_greening_record_items contains r.item if {
	count(vfh_parcels) > 0
	some r in data.o6_10.record_requirements.greening_records
	not r.item in greening_record_items
}

farm_obligation_violations contains {
	"rule_id": "O610-REC-GREENING",
	"reason": sprintf("Aufzeichnungen zur Begrünung unvollständig, es fehlen: %v", [sort(missing_greening_record_items)]),
} if {
	count(missing_greening_record_items) > 0
}

# o6_10 – Optionaler Zuschlag Einsatz von Organismen oder Pheromonen (Code EOP)
package oepul.o6_10

# O610-APP-EOP-CODE: Beantragung über Code EOP am Schlag, keine gesonderte Beantragung bis 31.12.
eop_parcels := [p | some p in vfh_parcels; params.eop_supplement_parcel_code in parcel_codes(p)]

eop_requested if count(eop_parcels) > 0

# O610-EOP-NO-OP-PO: keine Teilnahme an einem operationellen Programm mit Abgeltung von Organismen/Pheromonen
po := object.get(input, ["farm", "oepul", "producer_organisation"], {})

po_blocks_eop if {
	object.get(po, "is_member", false) == true
	object.get(po, "operational_programme_compensates_organisms_or_pheromones", false) == true
}

# O610-EOP-REQ-USE + O610-EOP-REPLACE-PSM: auf zumindest einem Schlag anrechenbarer Einsatz
creditable_use(p) if {
	u := object.get(p, ["operations", "organisms_pheromones"], {})
	object.get(u, "used", false) == true
	object.get(u, "per_register_application_rates", false) == true
	object.get(u, "replaces_psm_application", false) == true
}

eop_use_fulfilled if {
	some p in vfh_parcels
	creditable_use(p)
}

eop_rejections contains {
	"rule_id": "O610-EOP-NO-OP-PO",
	"reason": "Mitglied einer Erzeugerorganisation mit operationellem Programm, das Organismen oder Pheromone abgilt: Zuschlag nicht möglich",
} if {
	eop_requested
	po_blocks_eop
}

eop_rejections contains {
	"rule_id": "O610-EOP-REQ-USE",
	"reason": "Kein anrechenbarer Einsatz von Organismen oder Pheromonen gemäß Aufwandsmengen im Pflanzenschutzmittelregister, der einen Pflanzenschutzmitteleinsatz ersetzt",
} if {
	eop_requested
	not eop_use_fulfilled
}

default eop_supplement_granted := false

eop_supplement_granted if {
	eop_requested
	contract_valid
	count(eop_rejections) == 0
}

# O610-EOP-RECORDS
eop_record_items := {i | some i in object.get(input, ["documentation", "o6_10_organisms_pheromones_record_items"], [])}

missing_eop_record_items contains r.item if {
	eop_requested
	some r in data.o6_10.record_requirements.organisms_pheromones_records
	not r.item in eop_record_items
}

farm_obligation_violations contains {
	"rule_id": "O610-EOP-RECORDS",
	"reason": sprintf("Schlagbezogene Aufzeichnungen zu Organismen/Pheromonen unvollständig, es fehlen: %v", [sort(missing_eop_record_items)]),
} if {
	count(missing_eop_record_items) > 0
}

# O610-PREM-EOP-REDUCTION: Kürzung um 50 % bei Teilnahme an 12 oder 1B
eop_reduction_applies if {
	some m in rates.supplement_reduction.triggering_measures
	m in participating_measures
}

default eop_reduction_factor := 1

eop_reduction_factor := (100 - rates.supplement_reduction.reduction_percent) / 100 if eop_reduction_applies
